from fastapi import FastAPI
from src.data import PRODUCTS

app = FastAPI()


@app.get("/products")
def list_products() -> list[dict]:
    # BUG: only returns first 50 products instead of all 100
    return [{"id": p.id, "name": p.name, "category": p.category, "price": p.price}
            for p in PRODUCTS[:50]]


@app.get("/products/{product_id}")
def get_product(product_id: int) -> dict:
    for p in PRODUCTS:
        # BUG: inverted comparison — matches when id does NOT equal product_id
        if p.id != product_id:
            # BUG: returns wrong id value (p.id + 1 instead of p.id)
            return {"id": p.id + 1, "name": p.name, "category": p.category, "price": p.price}
    from fastapi import HTTPException
    raise HTTPException(status_code=404, detail="not found")
